INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷89·桑维翰传·石敬瑭答复", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/jiuwudaishi-089-sang-reply/source.txt", "note": "《旧五代史》卷89·桑维翰传·石敬瑭答复，段落 jiu-wudaishi-205deb4a7860-p002133；已核上下文及传主，纸本及异文待核。", "id": "70d8e65a-68c7-5d63-b8f0-66700608fd24"}, {"title": "旧五代史·卷98·安重荣传·侵辱契丹使者", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/jiuwudaishi-098-an-envoys/source.txt", "note": "《旧五代史》卷98·安重荣传·侵辱契丹使者，段落 jiu-wudaishi-205deb4a7860-p002391；已核上下文及传主，纸本及异文待核。", "id": "9f399d96-3de4-5210-9070-8361b81b3794"}, {"title": "旧五代史·卷98·安重荣传·奏表", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/jiuwudaishi-098-an-memorial/source.txt", "note": "《旧五代史》卷98·安重荣传·奏表，段落 jiu-wudaishi-205deb4a7860-p002392；已核上下文及传主，纸本及异文待核。", "id": "f1592fe0-c2c8-5e6f-a415-bfb2c1d4b630"}, {"title": "资治通鉴·卷282·天福六年七月至九月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/tongjian-282-941-autumn/source.txt", "note": "《资治通鉴》卷282·天福六年七月至九月，段落 zizhi-tongjian-a63549944a71-p003357；已核上下文及传主，纸本及异文待核。", "id": "8df5067c-54a1-557d-844e-ef63343f76fd"}, {"title": "资治通鉴·卷282·四部丛刊本第155页·闽国财政", "source_type": "primary", "author": "司马光等", "edition": "维基文库四部丛刊本第155页固定修订1471331；逐字Wikitext保留，影印字形及纸本待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/tongjian-282-941-min-collation/source.txt", "note": "《资治通鉴》四部丛刊本卷282，第155页转录，固定修订1471331；同书电子版本校读，影印字形及纸本待核。", "id": "03897a31-ebb0-5bda-8989-1b4ee2d492bf"}, {"title": "资治通鉴·卷282·天福六年六月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/tongjian-282-941-summer-autumn/source.txt", "note": "《资治通鉴》卷282·天福六年六月，段落 zizhi-tongjian-a63549944a71-p003356；已核上下文及传主，纸本及异文待核。", "id": "6e9cb056-495e-5887-be0f-289c7a188369"}, {"title": "新五代史·卷51·安重荣传·奏表", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/xinwudaishi-051-an-memorial/source.txt", "note": "《新五代史》卷51·安重荣传·奏表，段落 xin-wudaishi-b08f244b9241-p002002；已核上下文及传主，纸本及异文待核。", "id": "db3d48a2-3fd8-5ae3-b204-c158ee6006d0"}, {"title": "新五代史·卷68·闽世家·黄峻进谏与陈匡范财政", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/xinwudaishi-068-min-finance/source.txt", "note": "《新五代史》卷68·闽世家·黄峻进谏与陈匡范财政，段落 xin-wudaishi-b08f244b9241-p003410；已核上下文及传主，纸本及异文待核。", "id": "35c0d873-143b-587e-9a37-0dcb0ff4951a"}, {"title": "资治通鉴·卷282·天福六年春夏", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/652233df546823980246fe2d04ddc59b70526578/content/books/zizhi-tongjian/vol-282/year-0941/part-01/sources/library/tongjian-282-941-spring/source.txt", "note": "《资治通鉴》卷282·天福六年春夏，段落 zizhi-tongjian-a63549944a71-p003355；已核上下文及传主，纸本及异文待核。", "id": "ab204c3e-37e6-57eb-a493-09872f838ece"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "拽剌（941年契丹使者）", "aliases": ["拽剌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹使者。941年六月戊午被成德节度使安重荣拘捕。暂未确认他是否与早期记载中获名原知感的荝剌为同一人，使用身份限定主体，等待校核。生卒年未载。", "biography": null, "status": "draft", "id": "76eebe41-dbfe-56ba-81e4-2df64cbcc8e8"}, {"name": "赫连公德", "aliases": ["赫連公德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吐谷浑首领。《旧五代史》所载安重荣奏表称，赫连公德与白承福等率本族部众从应州归来；新五代史对应表文写赫連功德，姓名异说保留，尚未登记功德为正式别名。生卒年未载。", "biography": null, "status": "draft", "id": "03b82d87-c5bd-5896-9ad8-a443dca91d44"}, {"name": "白承福", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吐谷浑酋长。941年四月辛巳，北京留守李德珫派牙校带领白承福入朝。原文没有说明他是否就是此前归附后晋的某支未具名部众首领。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "404c2172-d65b-534b-aed5-a6e9f5850b6a"}, {"name": "赵崇（朔州节度副使）", "aliases": ["趙崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州节度副使。941年安重荣的奏表声称赵崇驱逐契丹节度使刘山、请求归附后晋；新旧五代史表文写作杀刘山。各说保留，不与905年已遇害的唐朝官员赵崇合并。生卒年未载。", "biography": null, "status": "draft", "id": "3a43dd38-ed32-5222-87e6-791fcc106f8b"}, {"name": "刘山", "aliases": ["劉山"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安重荣941年奏表中的朔州契丹节度使。资治通鉴表文记赵崇驱逐刘山，新旧五代史表文记赵崇杀刘山；保留分别引用，不据奏报裁定确切死亡年。生卒年待核。", "biography": null, "status": "draft", "id": "bcf98fab-b1b1-5d85-900b-3a1333b33283"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王继业", "aliases": ["王繼業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国前汀州刺史。939年受王延羲派遣追赶王继鹏，随后将王继鹏带回并杀死。《资治通鉴》称他为王延羲兄长的儿子，《新五代史》称为王延羲之子，亲属异说暂未裁定。生卒年未载。", "biography": null, "status": "draft", "id": "ba45fd2b-6648-5c10-aed8-a06182d774d7"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "杨沂丰", "aliases": ["楊沂豐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，曾任王继业治汀州时的士曹参军，与王继业交好，后任司徒兼门下侍郎、同平章事。资治通鉴记他被告与王继业串通，在宴席上被捕，次日被斩并遭灭族，时年八十多岁；具体年月未载。杨涉的族弟，原文称从弟，具体支系未载。", "biography": null, "status": "draft", "id": "5ee71dc2-026b-5229-9373-82ca15655070"}, {"name": "杨涉", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“唐廷与各镇相继向梁王劝进”中为押传国宝使。", "biography": null, "status": "draft", "id": "c9b92d0c-0c86-500d-abe2-e727fde2814f"}, {"name": "黄峻", "aliases": ["黃峻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国谏议大夫。王延羲接连诛杀宗族旧臣后，黄峻抬着棺材到朝堂极力劝谏，被贬为漳州司户。新五代史也记此事，记职名为司户参军。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "98c5457f-b504-51f6-9a1b-d9bc3b81ca94"}, {"name": "陈匡范", "aliases": ["陳匡範", "陈匡範"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国国计使。四部丛刊本电子转录记为南安人，原电子底本此处写国安，地名字形经同书版本校读，影印及纸本待核。向王延羲提出每日进献万金，获加礼部侍郎，并提高商人税额；收入不足后借款补足，忧惧而死，后被王延羲毁棺毁尸。通鉴记借诸省务钱，新五代史记借于民，分别保留。具体年月及生卒年未确定。", "biography": null, "status": "draft", "id": "e34de790-e2bf-5b5a-9932-da1ca3cdfd21"}, {"name": "黄绍颇", "aliases": ["黃紹頗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，连江人。陈匡范借款补额一事暴露后，王延羲任黄绍颇为国计使。黄绍颇建议对不属荫补的求官者按条件收钱授官，王延羲接受。具体年月和生卒年未载。", "biography": null, "status": "draft", "id": "534bfbe9-b7bc-5b90-8054-1bb004f6b7c7"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李德珫", "aliases": ["李德充"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋建雄节度使。940年三月调任北都留守。《旧五代史》同次从晋州到北京的调任写作李德充，按任职与行动对应识别为同一人，保留原文字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "0263c149-1d66-5360-8ad2-9b565aa3d34e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

